from collections import Counter

def transform(grid):
    rows = len(grid)
    # Find background row (most common complete row)
    row_counts = Counter([tuple(r) for r in grid])
    background = max(row_counts, key=row_counts.get)

    # Fill in background rows at their positions
    output = [None] * rows
    for i, row in enumerate(grid):
        if row == background:
            output[i] = row

    # Non-background rows shift down by 1
    for i, row in enumerate(grid):
        if row != background:
            target = (i + 1) % rows
            if output[target] is None:
                output[target] = row

    return output

